def unwrap_sample_sheet_from_lane_list(sample_sheet):
    if isinstance(sample_sheet, list):
        if len(sample_sheet) == 1:
            lane_payload = sample_sheet[0]
        else:
            lane_payload = next(
                (item for item in sample_sheet if item.get("lane") == 1), None
            )
        if isinstance(lane_payload, dict):
            unwrapped = dict(lane_payload)
            unwrapped.pop("lane", None)
            return unwrapped
    return sample_sheet


def port_legacy_quote_data(apps, schema_editor):
    Flowcell = apps.get_model("flowcell", "Flowcell")
    SequencingQuote = apps.get_model("flowcell", "SequencingQuote")

    for flowcell in Flowcell.objects.all():
        provider_id = getattr(flowcell, "sequencing_provider_id", None)
        raw_quote_id = getattr(flowcell, "sequencing_provider_quote_id", None)

        if provider_id is None or raw_quote_id in (None, ""):
            continue

        quote_id = str(raw_quote_id).strip()
        if not quote_id:
            continue

        quote, _ = SequencingQuote.objects.get_or_create(
            sequencing_provider_id=provider_id,
            quote_id=quote_id,
            defaults={
                "date_created": getattr(flowcell, "create_time", None).date()
                if getattr(flowcell, "create_time", None)
                else timezone.now().date(),
                "data_delivery_method": "",
                "price": None,
                "notes": "",
            },
        )
        flowcell.sequencing_quotes.add(quote)


def reverse_port_legacy_quote_data(apps, schema_editor):
    Flowcell = apps.get_model("flowcell", "Flowcell")
    for flowcell in Flowcell.objects.all():
        flowcell.sequencing_quotes.clear()


def remove_internal_provider_and_update_sample_sheets(apps, schema_editor):
    Flowcell = apps.get_model("flowcell", "Flowcell")
    SequencingProvider = apps.get_model("flowcell", "SequencingProvider")

    for flowcell in Flowcell.objects.all():
        unwrapped = unwrap_sample_sheet_from_lane_list(flowcell.sample_sheet)
        if unwrapped != flowcell.sample_sheet:
            flowcell.sample_sheet = unwrapped
            flowcell.save(update_fields=["sample_sheet"])

    SequencingProvider.objects.filter(name="Internal").delete()


